def _quantile_sample(uniforms: torch.Tensor, tables: list[list[float]]) -> torch.Tensor:
    probabilities = torch.tensor(QUANTILE_PROBABILITIES,dtype=torch.float32,device='cpu')
    table = torch.tensor(tables,dtype=torch.float32,device='cpu')
    # Uniforms use [T,H,D] or [T,H]. Quantile tables are indexed by head.
    lower = torch.searchsorted(probabilities,uniforms.contiguous(),right=True).sub(1).clamp(0,len(probabilities)-2)
    fraction = (uniforms-probabilities[lower])/(probabilities[lower+1]-probabilities[lower])
    heads = torch.arange(table.shape[0],device='cpu').view(1,-1,*([1] if uniforms.ndim==3 else []))
    return table[heads,lower]*(1-fraction)+table[heads,lower+1]*fraction


def _make_inputs(
    tokens: int,
    requests: int,
    state_nonzero: bool = False,
    sequence_lengths: list[int] | None = None,
    seed: int | None = None,
    dtype: str = 'bfloat16',
    device: str = 'cuda',
) -> dict[str,object]:
    if type(tokens) is not int or type(requests) is not int or not 1<=tokens<=8192 or not 1<=requests<=16:
        raise ValueError('geometry differs from the observed TP2 C16 prefill ABI')
    if dtype!='bfloat16' or type(state_nonzero) is not bool:
        raise ValueError('dtype or state regime differs from the input contract')
    seed = (torch.initial_seed() % (2**63)) if seed is None else seed
    if type(seed) is not int or not 0<=seed<2**63:
        raise ValueError('seed must be a nonnegative 63-bit integer')
    if sequence_lengths is None:
        lengths = [tokens//requests+(i<tokens%requests) for i in range(requests)]
    else:
        if (not isinstance(sequence_lengths,list) or len(sequence_lengths)!=requests
                or any(type(x) is not int or x<0 for x in sequence_lengths)
                or sum(sequence_lengths)!=tokens):
            raise ValueError('sequence lengths must conserve the observed packed tokens')
        lengths = sequence_lengths.copy()
    generator = torch.Generator(device='cpu').manual_seed(seed)
    values = {}
    for name,heads in (('q',8),('k',8),('v',24)):
        uniforms = torch.rand((tokens,heads,128),generator=generator,dtype=torch.float32,device='cpu')
        values[name] = _quantile_sample(uniforms,PROFILES[name]).unsqueeze(0).to(device=device,dtype=torch.bfloat16)
    normal = torch.randn((tokens,24,2),generator=generator,dtype=torch.float32,device='cpu')
    correlation = torch.tensor(GATE_BETA_CORRELATION,dtype=torch.float32,device='cpu')
    gate_normal = normal[:,:,0]
    beta_normal = correlation*gate_normal+(1-correlation.square()).clamp_min(0).sqrt()*normal[:,:,1]
    gate_uniform = ((gate_normal/math.sqrt(2)).erf()+1)*.5
    beta_uniform = ((beta_normal/math.sqrt(2)).erf()+1)*.5
    values['g'] = -_quantile_sample(gate_uniform,PROFILES['g']).exp().unsqueeze(0).to(device=device)
    values['beta'] = _quantile_sample(beta_uniform,PROFILES['beta']).clamp(0,1).unsqueeze(0).to(device=device,dtype=torch.bfloat16)
    initial = torch.zeros((requests,24,128,128),dtype=torch.float32,device=device)
    if state_nonzero:
        spectrum = torch.tensor(STATE_SINGULAR_VALUES,dtype=torch.float32,device='cpu')
        means = torch.tensor(STATE_HEAD_MEAN,dtype=torch.float32,device='cpu')[:,None,None]
        row_scale = torch.tensor(STATE_ROW_SCALE,dtype=torch.float32,device='cpu')[:,:,None]
        column_scale = torch.tensor(STATE_COLUMN_SCALE,dtype=torch.float32,device='cpu')[:,:,None]
        for request in range(requests):
            left = torch.randn((24,128,128),generator=generator,dtype=torch.float32,device='cpu')
            right = torch.randn((24,128,128),generator=generator,dtype=torch.float32,device='cpu')
            left = torch.linalg.qr(left*row_scale.clamp_min(1e-12)).Q
            right = torch.linalg.qr(right*column_scale.clamp_min(1e-12)).Q
            # QR's deterministic column signs otherwise create coordinate bias.
            left *= torch.randint(2,(24,1,128),generator=generator,device='cpu')*2-1
            right *= torch.randint(2,(24,1,128),generator=generator,device='cpu')*2-1
            state = (left*spectrum[:,None,:]) @ right.transpose(-1,-2)
            initial[request].copy_((state+means).to(device=device))
    cumulative = [0]
    for length in lengths:
        cumulative.append(cumulative[-1]+length)
    return {'q':values['q'],'k':values['k'],'v':values['v'],
            'g':values['g'],'beta':values['beta'],'initial_state':initial,
            'cu_seqlens':torch.tensor(cumulative,dtype=torch.int32,device=device),
            'output_final_state':True,'head_first':False,'use_qk_l2norm_in_kernel':True}
